<script setup lang="ts">
import {computed,onBeforeUnmount,reactive,ref,shallowReactive,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useSession} from '../../session'
import {ApiError} from '../../api'
import {ObjectLease} from '../../object-lease'
import {uuid,decimal,type QuoteReferences} from '../finance/finance-client'
import {yuanFromCents} from '../finance/quote-draft'
import {feeOwner,feeTransport,canReadFees,parseFee,parseFeePreview,type FeeQuotePreview,type FeeApplication,type FeeAction,type FeePage} from './fee-client'
import {FeeWork,retainedFees,type FeeTarget} from './fee-work'
const auth=useSession(),route=useRoute(),router=useRouter(),input=ref(''),page=ref(1),selection=ref(''),reason=ref(''),consent=ref(false),action=ref<FeeAction|null>(null)
let alive=true
const ticket=computed(()=>String(route.params.id??'')),application=computed(()=>String(route.params.applicationId??'')),owner=computed(()=>JSON.stringify(feeOwner(auth))),context=()=>JSON.stringify([owner.value,route.fullPath]),listContext=()=>context()+':'+page.value,wire=feeTransport(auth,()=>alive),hasTicket=computed(()=>uuid(ticket.value))
const list=reactive(new ObjectLease<FeePage>(auth,listContext,async()=>{const stamp=listContext(),p=page.value,r=await wire.send<FeePage>('GET','/approval/fees?ticketId='+ticket.value+'&page='+p+'&size=20',undefined,()=>listContext()===stamp);if(!r||r.page!==p||r.size!==20||typeof r.hasMore!=='boolean'||!Array.isArray(r.items)||r.items.length>20||new Set(r.items.map(v=>v.applicationId)).size!==r.items.length)throw Error('申请列表分页无法确认');return{...r,items:r.items.map(v=>parseFee(v,ticket.value))}})),detail=reactive(new ObjectLease<FeeApplication>(auth,context,async()=>{const stamp=context(),id=application.value;return parseFee(await wire.send('GET','/approval/fees/'+id,undefined,()=>context()===stamp),ticket.value,id)})),catalog=reactive(new ObjectLease<QuoteReferences>(auth,context,async()=>{const stamp=context(),r=await wire.send<QuoteReferences>('GET','/ticket/tickets/'+ticket.value+'/fee-quote-references',undefined,()=>context()===stamp);if(!r||!Array.isArray(r.items)||r.items.length>20||r.items.some(v=>!uuid(v.quoteId)||!uuid(v.groupId)||!uuid(v.roundId)||!decimal(v.generation)||!decimal(v.quoteVersion))||new Set(r.items.map(v=>v.quoteId)).size!==r.items.length)throw Error('当前报价引用无法确认');return r}))
const previewContext=()=>context()+':'+selection.value,preview=reactive(new ObjectLease<FeeQuotePreview>(auth,previewContext,async()=>{const s=selected.value;if(!s)throw Error('请选择已授权报价引用');const stamp=previewContext();return parseFeePreview(await wire.send('GET','/approval/fees/quote-context?ticketId='+ticket.value+'&groupId='+s.groupId+'&quoteId='+s.quoteId,undefined,()=>previewContext()===stamp),ticket.value,s.groupId,s.quoteId)}))
const selected=computed(()=>catalog.value?.items.find(q=>q.quoteId===selection.value)),target=()=>detail.value?{applicationId:detail.value.applicationId,ticketId:ticket.value,groupId:detail.value.groupId,quoteId:detail.value.quoteId}:null
function allowed(a:FeeAction,t:FeeTarget){if(!feeOwner(auth)||t.ticketId!==ticket.value)return false;if(a==='submit')return !!auth.identity?.permissions.includes('approval.fees.submit')&&!!preview.value?.canSubmit&&preview.value.quoteId===t.quoteId&&preview.value.groupId===t.groupId&&!!catalog.value&&catalog.value.items.some(q=>q.groupId===t.groupId&&q.quoteId===t.quoteId);const d=detail.value;return !!d&&d.applicationId===t.applicationId&&d.groupId===t.groupId&&d.quoteId===t.quoteId&&d.actions.includes(a)&&(!['approve','reject'].includes(a)||d.applicantUserId!==auth.identity?.userId)}
const work=shallowReactive(new FeeWork(wire,()=>feeOwner(auth),allowed,o=>reactive(o),()=>crypto.randomUUID(),e=>{if(e instanceof ApiError&&[401,403,404,503].includes(e.status)){detail.clear();list.clear();catalog.clear();preview.clear();consent.value=false;action.value=null}})),recoveries=computed(()=>{const o=feeOwner(auth);return o?Array.from(retainedFees.entries()).flatMap(([k,v])=>{const [tenant,actor,ticketId]=JSON.parse(k);return tenant===o.tenant&&actor===o.actor?[{ticketId,key:v.key}]:[]}):[]})
function clearForm(){consent.value=false;reason.value='';action.value=null;selection.value=''}
async function refresh(reset=true){if(reset)clearForm();const oldVersion=detail.value?.version;if(!hasTicket.value||!canReadFees(auth.identity))return;await list.refresh();if(uuid(application.value))await detail.refresh();if(oldVersion!==detail.value?.version){action.value=null;consent.value=false}if(auth.identity?.permissions.includes('approval.fees.submit'))await catalog.refresh()}
async function open(){if(uuid(input.value))await router.push('/tickets/'+input.value+'/fee-approvals')}
async function submit(){if(!consent.value||!selected.value)return;const s=selected.value;await work.start('submit',{applicationId:crypto.randomUUID(),ticketId:ticket.value,groupId:s.groupId,quoteId:s.quoteId});consent.value=false}
async function decide(){const t=target();if(!t||!action.value||!consent.value)return;try{await work.start(action.value,t,detail.value!.version,reason.value);consent.value=false}catch(e){work.message=e instanceof Error?e.message:'请核对操作'}}
async function recheckOriginal(){const op=work.operation;if(!op||work.busy)return;if(op.action==='submit'){await catalog.refresh();selection.value=op.target.quoteId;if(selected.value)await preview.refresh()}else if(application.value!==op.target.applicationId)await router.push('/tickets/'+ticket.value+'/fee-approvals/'+op.target.applicationId);else await detail.refresh()}
async function next(){const id=work.operation?.target.applicationId;work.next();if(id&&application.value!==id)await router.push('/tickets/'+ticket.value+'/fee-approvals/'+id);else await refresh()}
watch(()=>[owner.value,route.fullPath],()=>{work.unbind();detail.clear();list.clear();catalog.clear();preview.clear();page.value=1;clearForm();if(hasTicket.value)work.bind(ticket.value);void refresh()},{immediate:true,flush:'sync'})
watch(selection,()=>{preview.clear();consent.value=false;if(selected.value)void preview.refresh()},{flush:'sync'})
function visibility(){clearForm();if(document.visibilityState==='hidden'){detail.clear();list.clear();catalog.clear();preview.clear()}else void refresh()}
document.addEventListener('visibilitychange',visibility);let last=Date.now();const timer=setInterval(()=>{detail.expire();list.expire();catalog.expire();preview.expire();if(Date.now()-last>25000&&!work.busy&&document.visibilityState!=='hidden'){last=Date.now();void refresh(false)}},1000)
onBeforeUnmount(()=>{alive=false;work.dispose();detail.dispose();list.dispose();catalog.dispose();preview.dispose();clearInterval(timer);document.removeEventListener('visibilitychange',visibility)})
const names:Record<string,string>={WAITING_CUSTOMER:'等待客户确认',WAITING_CONFIGURATION:'等待合格审核人配置',PENDING_SUPERVISOR:'等待主管审核',WAITING_FINANCE:'等待财务审核',COMPLETED:'内部审批完成',REJECTED:'已拒绝',WITHDRAWN:'已撤回',TERMINATED:'旧来源已终止',submit:'提交内部审批',refresh:'显式刷新等待条件',approve:'批准当前节点',reject:'拒绝当前节点',withdraw:'申请人撤回'}
</script>
<template>
<section class="page-heading"><RouterLink to="/tickets">← 工单</RouterLink><h1>内部费用审批</h1><p>客户确认只是审批前置；内部完成也不等于应收、实际收款或所有付费执行已授权。当前审核资格与非自批由服务端再次核验。</p></section>
<section class="panel"><label>工单UUID<input v-model="input"></label><button :disabled="!uuid(input)" @click="open">查询当前授权费用申请</button><p v-for="r in recoveries" :key="r.key"><RouterLink :to="'/tickets/'+r.ticketId+'/fee-approvals'">恢复原动作{{r.key}}</RouterLink></p></section>
<section v-if="hasTicket" class="panel"><h2>当前申请列表</h2><button :disabled="list.busy||detail.busy" @click="refresh()">重新核验列表、详情与当前动作</button><p v-if="list.error" role="alert">{{list.error}}</p><ul><li v-for="v in list.value?.items" :key="v.applicationId"><RouterLink :to="'/tickets/'+ticket+'/fee-approvals/'+v.applicationId">{{names[v.state]}} · {{v.applicationId}} · 版本{{v.version}}</RouterLink></li></ul><button :disabled="page<=1||list.busy" @click="page--;list.clear();list.refresh()">上一页</button><button :disabled="!list.value?.hasMore||list.busy" @click="page++;list.clear();list.refresh()">下一页</button></section>
<section v-if="hasTicket&&auth.identity?.permissions.includes('approval.fees.submit')&&!work.operation" class="panel"><h2>原工程师发起内部费用审批</h2><p>仅提交原报价引用；不传金额basis、阈值、已确认、已批准或当前资格。服务端核验当前原工程师、当前报价与冻结代际。</p><p v-if="catalog.error" role="alert">{{catalog.error}}。未提供授权目录时不能以手填UUID替代。</p><label for="fee-quote-selection">授权报价引用</label><select id="fee-quote-selection" v-model="selection"><option value="">请选择已提交报价，历史引用不保证仍有效</option><option v-for="q in catalog.value?.items" :key="q.quoteId" :value="q.quoteId">报价版本{{q.quoteVersion}} · {{q.quoteId}}</option></select><p v-if="preview.error" role="alert">{{preview.error}}</p><div v-if="preview.value"><p>原报价版本{{preview.value.quoteVersion}} · 冻结报价{{yuanFromCents(preview.value.basis.qCents)}}元；{{preview.value.customerConfirmation?'已有原报价版本客户确认':'尚无客户确认，提交后须等待客户，不能审核'}}。</p><p>{{preview.value.canSubmit?'本次查询允许提交，POST仍核当前资格':'当前不可创建新申请'}}</p><RouterLink v-if="preview.value.existingApplicationId" :to="'/tickets/'+ticket+'/fee-approvals/'+preview.value.existingApplicationId">查看已有申请，不重复创建</RouterLink></div><label><input v-model="consent" type="checkbox">我已核对本次原报价引用，明确发起内部审批</label><button :disabled="!selected||!preview.value?.canSubmit||!consent||work.busy" @click="submit">提交内部费用审批</button></section>
<section v-if="uuid(application)" class="panel"><p v-if="detail.error" role="alert">{{detail.error}}</p><template v-if="detail.value"><h2>{{names[detail.value.state]}}</h2><p>申请{{detail.value.applicationId}} · 当前版本{{detail.value.version}} · 原报价版本{{detail.value.quoteVersion}}</p><p>冻结金额：报价{{yuanFromCents(detail.value.basis.qCents)}}元，成本{{yuanFromCents(detail.value.basis.cCents)}}元，历史批准{{yuanFromCents(detail.value.basis.hCents)}}元，基数{{yuanFromCents(detail.value.basis.bCents)}}元；规则{{detail.value.basis.ruleVersion}}。</p><ul aria-label="原报价冻结费用明细"><li v-for="l in detail.value.lines" :key="l.id">{{l.kind==='LABOR'?'人工':l.kind==='PART'?'备件':'其他'}} · {{yuanFromCents(l.amountCents)}}元 · 原工单{{l.ticketId}} · 原轮次{{l.roundId}}</li></ul><p>冻结代际{{detail.value.generation}} · 覆盖摘要{{detail.value.coverageDigest}}</p><p>当前报价{{detail.value.chargesCustomer?'向客户收费':'不向客户收费'}}；{{detail.value.customerConfirmation?'已有本报价版本客户确认事实':'没有本报价版本客户确认事实'}}。{{detail.value.financialReviewRequired?'冻结分支需要财务审核':'冻结分支不要求财务审核'}}。</p><p v-if="detail.value.completionId">内部完成事实{{detail.value.completionId}}，不表示已收款。</p><p v-if="detail.value.terminalReason">终止/决定理由：{{detail.value.terminalReason}}</p><template v-if="!work.operation"><button v-for="a in detail.value.actions" :key="a" :disabled="!allowed(a,target()!)" @click="action=a;consent=false;reason=''">{{names[a]}}</button><template v-if="action"><label v-if="action!=='refresh'">本次理由<textarea v-model="reason" maxlength="500"/></label><label><input v-model="consent" type="checkbox">确认对当前版本执行{{names[action]}}；未知结果不自动重发</label><button :disabled="!consent||work.busy" @click="decide">明确执行此内部审批动作</button></template></template></template></section>
<section v-if="work.operation" class="panel"><h2>原内部审批动作恢复</h2><p>{{names[work.operation.action]}} · 原UUID{{work.operation.key}} · {{work.operation.state}}</p><p>历史回执不覆盖当前详情，回执actions必须为空。401/403/503不开放重交；404仅本次未观察到。</p><button :disabled="work.busy" @click="work.recover()">只查询原内部审批UUID</button><button :disabled="work.busy" @click="recheckOriginal">重新核验原动作当前资格</button><button v-if="work.operation.state==='NOT_OBSERVED'&&allowed(work.operation.action,work.operation.target)" :disabled="work.busy" @click="work.recover(false)">显式同UUID同参数继续原动作</button><p v-if="work.operation.receipt&&(detail.value?.applicationId===work.operation.target.applicationId||list.value?.items.some(v=>v.applicationId===work.operation!.target.applicationId))">原动作历史状态{{names[work.operation.receipt.state]}} · 当时版本{{work.operation.receipt.version}}</p><button v-if="work.operation.state==='SUCCEEDED'" :disabled="work.busy" @click="next">明确重新查询当前申请</button></section><p v-if="work.message" role="status" class="notice">{{work.message}}</p>
</template>
<style scoped>label{display:block;margin:12px 0}input:not([type=checkbox]),textarea,select{display:block;max-width:100%;width:600px;box-sizing:border-box;padding:9px;font:inherit}button{padding:9px;margin:6px;font:inherit}p{overflow-wrap:anywhere}</style>
